<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Work Shifts">
      <ExportWorkShiftsList
        v-if="isAdminOrManager"
        :params="params"
        :disabled="!workshiftData || workshiftData.total_count === 0"
      />
    </PageTitle>
    <WorkshiftListFilters :params="params" />
    <Card>
      <CardContent class="!p-0 !md:p-0">
        <AppLoader v-if="isLoading" variant="inline" subject="work shifts" />
        <AppError
          v-else-if="error"
          :error="error"
          title="Failed to load work shifts"
          variant="table"
          :action="refetch"
          action-text="Retry"
        />
        <AppEmpty
          v-else-if="!workshiftData || workshiftData.items.length === 0"
          subject="work shifts"
          variant="table"
        />
        <template v-else>
          <ResponsiveTable rounded>
            <ResponsiveTableHeader>
              <ResponsiveTableHead v-if="isAdminOrManager" class="text-accent-foreground text-xs sm:text-sm leading-6">
                Canvasser
              </ResponsiveTableHead>
              <ResponsiveTableHead class="text-accent-foreground text-xs sm:text-sm leading-6">
                Project
              </ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit text-nowrap">Start Time</ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit text-nowrap">End Time</ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit text-nowrap">Net Hours</ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit">Status</ResponsiveTableHead>
            </ResponsiveTableHeader>
            <ResponsiveTableBody>
              <ResponsiveTableEmpty
                v-if="workshiftData.items.length === 0"
                :colspan="isAdminOrManager ? 6 : 5"
                :cols="4"
                :cols-sm="4"
                cell-class="text-center"
              >
                <AppEmpty subject="work shifts" variant="table" />
              </ResponsiveTableEmpty>
              <ResponsiveTableRow
                v-for="item in workshiftData.items"
                v-else
                :key="item.id"
                :to="{ name: 'workshifts-id', params: { id: item.id } }"
              >
                <ResponsiveTableCell v-if="isAdminOrManager" :cols="4" :cols-sm="4" label="Canvasser">
                  <UserNameWithCompany :user="item.canvasser" />
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="4" :cols-sm="4" label="Project">
                  <p class="text-base line-clamp-2">{{ item.project.name }}</p>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="1" label="Start Time">
                  <p class="text-base md:text-center">
                    {{ formatDateTzToFormat(item.start_time, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
                  </p>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="1" label="End Time">
                  <p class="text-base md:text-center">
                    <template v-if="item.end_time">
                      {{ formatDateTzToFormat(item.end_time, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
                    </template>
                    <span v-else class="text-muted-foreground">Ongoing</span>
                  </p>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="1" label="Net Hours">
                  <p class="text-base md:text-center">
                    <template v-if="item.net_hours != null">
                      {{ formatHoursDuration(item.net_hours) }}
                    </template>
                    <span v-else class="text-muted-foreground">N/A</span>
                  </p>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="1" label="Status">
                  <div class="flex md:justify-center">
                    <Badge :variant="getWorkshiftStatusBadge(item.status).variant">
                      {{ getWorkshiftStatusBadge(item.status).label }}
                    </Badge>
                  </div>
                </ResponsiveTableCell>
              </ResponsiveTableRow>
            </ResponsiveTableBody>
            <ResponsiveTableFooter
              v-if="workshiftData.total_count > 0"
              :colspan="isAdminOrManager ? 6 : 5"
              :cols="4"
              :cols-sm="4"
            >
              <AppPagination
                :page="params.page"
                :size="params.size"
                :total="workshiftData.total_count"
                label="work shifts"
              />
            </ResponsiveTableFooter>
          </ResponsiveTable>
        </template>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import {
  getWorkShiftList,
  type GetWorkShiftListData,
  type GetWorkShiftListResponse,
  type SortType,
  type WorkShiftSortBy,
  type WorkShiftStatus,
} from '~/client';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';
import { getWorkshiftStatusBadge } from '~/constants/workshifts/workshiftStatuses';

definePageMeta({
  roles: ['admin'],
  backLabel: 'work shifts',
});

useHead({
  title: 'Work Shifts',
});

const route = useRoute();
const { timezone, isAdminOrManager } = useUserRole();

const params = computed(() => {
  const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
    route.query.subcontractor_company_ids
  );

  const urlParams = {
    ...parsePagination(route.query),
    sort_by: (route.query.sort_by as WorkShiftSortBy) || 'start_time',
    sort_type: isSortType(route.query.sort_type as string) ? (route.query.sort_type as SortType) : 'desc',
    statuses: processArrayQueryParameterFromUrl<WorkShiftStatus>(route.query.statuses),
    canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
    project_ids: processArrayQueryParameterFromUrl(route.query.project_ids),
    subcontractor_company_ids,
    include_unassigned,
    start_date_from: (route.query.start_date_from as string) || undefined,
    start_date_to: (route.query.start_date_to as string) || undefined,
    net_hours_min: route.query.net_hours_min ? Number(route.query.net_hours_min) : undefined,
    net_hours_max: route.query.net_hours_max ? Number(route.query.net_hours_max) : undefined,
    timezone: timezone.value,
  };

  return Object.fromEntries(Object.entries(urlParams).filter(([_, value]) => value !== undefined)) as typeof urlParams;
});

const {
  data: workshiftData,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['workshifts-list', params.value],
  query: (): Promise<GetWorkShiftListResponse> =>
    getWorkShiftList({
      composable: '$fetch',
      query: params.value,
    }),
  staleTime: 0,
});
</script>
